<?php /** @var \Sysfera\Plugin $sf @var string $tab @var bool $manage @var array $act @var array $names */
include __DIR__ . '/_nav.php'; $open = array_filter($act['lines'], fn($l) => $l['status'] === 'proposed'); ?>
<div class="page-h"><h1><?= e($sf->t('stocktake_act')) ?> <span class="gi-st"><?= e($sf->t('sts_' . $act['status'])) ?></span></h1><span class="row"><a class="btn" href="<?= e($sf->url('/stocktake')) ?>">←</a><button class="btn" onclick="window.print()"><?= e($sf->t('print')) ?></button></span></div>
<p class="muted"><?= e($names[$act['warehouse_id']] ?? '') ?> · <?= e($act['started_at']) ?> → <?= e($act['submitted_at'] ?: '…') ?> <?= e($act['submitted_by']) ?> · <code><?= e($act['stocktake']) ?></code></p>
<?php if ($act['status'] === 'open'): ?><div class="hint"><?= e($sf->t('stocktake_waiting')) ?></div><?php endif; ?>
<?php if ($manage && $open): ?><form method="post" class="card row"><?= csrf_field() ?><input type="hidden" name="stocktake" value="<?= e($act['stocktake']) ?>"><input name="note" placeholder="<?= e($sf->t('ret_note')) ?>" maxlength="300"><button class="btn primary" name="do" value="approve_all"><?= e($sf->t('adj_approve_all')) ?></button></form><?php endif; ?>
<div class="card flush"><table class="tbl"><thead><tr><th><?= e($sf->t('adj_act')) ?></th><th><?= e($sf->t('col_barcode')) ?></th><th><?= e($sf->t('col_name')) ?></th><th><?= e($sf->t('adj_expected')) ?></th><th><?= e($sf->t('adj_counted')) ?></th><th><?= e($sf->t('adj_diff')) ?></th><th><?= e($sf->t('status')) ?></th><th></th></tr></thead><tbody>
<?php foreach ($act['lines'] as $l): ?><tr><td><?= e($l['act']) ?></td><td><code><?= e($l['barcode']) ?></code></td><td><?= e($l['name']) ?><?= !empty($l['uncounted']) ? ' <small class="muted">(' . e($sf->t('adj_uncounted')) . ')</small>' : '' ?></td><td><?= (int)$l['expected'] ?></td><td><?= (int)$l['counted'] ?></td>
  <td><b class="<?= $l['diff'] < 0 ? 'bad' : 'warn' ?>"><?= $l['diff'] > 0 ? '+' : '' ?><?= (int)$l['diff'] ?></b></td><td><span class="gi-st"><?= e($sf->t('adjs_' . $l['status'])) ?></span><?php if (!empty($l['decided_by'])): ?><br><small class="muted"><?= e($l['decided_by']) ?> <?= e($l['decided_at']) ?> <?= e($l['note'] ?? '') ?></small><?php endif; ?></td>
  <td><?php if ($manage && $l['status'] === 'proposed'): ?><form method="post" class="row"><?= csrf_field() ?><input type="hidden" name="stocktake" value="<?= e($act['stocktake']) ?>"><input type="hidden" name="ref" value="<?= e($l['ref']) ?>"><input name="note" maxlength="300" size="14" placeholder="<?= e($sf->t('ret_note')) ?>"><button class="btn sm primary" name="do" value="approve"><?= e($sf->t('ret_approve')) ?></button><button class="btn sm" name="do" value="reject"><?= e($sf->t('ret_reject')) ?></button></form><?php endif; ?></td></tr><?php endforeach; ?>
<?php if (!$act['lines']): ?><tr><td colspan="8" class="muted"><?= e($sf->t($act['status'] === 'open' ? 'stocktake_waiting' : 'stocktake_clean')) ?></td></tr><?php endif; ?></tbody></table></div>
